WITH enriched AS (SELECT id, account_id, txn_type, amount, txn_time, merchant, is_flagged, ROUND(amount / SUM(amount) OVER (PARTITION BY txn_type, merchant), 4) AS amount_share, PERCENT_RANK() OVER (ORDER BY amount NULLS LAST) AS amount_percent_rank, NTILE(10) OVER (PARTITION BY merchant, txn_type ORDER BY amount, id) AS amount_bucket FROM transactions) SELECT CASE WHEN amount_share >= 0.9 THEN 'LARGE' ELSE 'SMALL' END AS amount_share_tier, merchant, DATE_TRUNC('MONTH', txn_time) AS activity_month, MAX(txn_time) AS ended_at, COUNT(DISTINCT id) AS distinct_ids, PERCENTILE_APPROX(amount_bucket, 0.5) AS amount_bucket_p50, PERCENT_RANK() OVER (PARTITION BY CASE WHEN amount_share >= 0.9 THEN 'LARGE' ELSE 'SMALL' END ORDER BY PERCENTILE_APPROX(amount_bucket, 0.5) DESC) AS amount_bucket_p50_percent_rank FROM enriched GROUP BY CASE WHEN amount_share >= 0.9 THEN 'LARGE' ELSE 'SMALL' END, merchant, DATE_TRUNC('MONTH', txn_time) ORDER BY amount_share_tier
